export type UserId = string & { readonly brand: 'UserId' };
export type User = { id: UserId; email: string };
export type JobStatus = 'queued' | 'running' | 'done' | 'failed';
export type Session = { id: string };

/** Get the user. */
export async function getUser(id: UserId): Promise<User | null> {
  return db.users.findById(id);
}

/** Looks up the session in Redis and retries the query twice. */
export function sessionFor(id: UserId): Session | undefined {
  return sessions.get(id);
}

/** Terminal states (`done`, `failed`) are ignored; see `JobStatus`. */
export function handle(status: JobStatus): void {
  if (status === 'done' || status === 'failed') return;
  run(status);
}

export function prepareHeaders(headers: Headers): void {
  // Validate the input
  // node-fetch#1767: redirect + custom Host is dropped. Remove when on undici.
  headers.delete('host');
}

declare const db: { users: { findById(id: UserId): Promise<User | null> } };
declare const sessions: { get(id: UserId): Session | undefined };
declare function run(status: JobStatus): void;

